class DebitAccountServiceTest {

    private static final String ACTIVE = "A";
    private static final String INACTIVE = "I";

    private static final long ACCOUNT = 1234567890L;

    /** In-memory fake of CUENTAS recording every call. */
    private static final class FakeAccounts implements AccountRepository {
        final Map<Long, Account> store = new HashMap<>();
        final List<Long> reads = new ArrayList<>();
        final List<Object[]> updates = new ArrayList<>();

        FakeAccounts with(Account account) {
            store.put(account.accountNumber(), account);
            return this;
        }

        @Override
        public Optional<Account> findByNumber(Long accountNumber) {
            reads.add(accountNumber);
            return Optional.ofNullable(store.get(accountNumber));
        }

        @Override
        public int updateBalance(Long accountNumber, BigDecimal balance) {
            updates.add(new Object[] {accountNumber, balance});
            Account current = store.get(accountNumber);
            if (current == null) {
                return 0;
            }
            store.put(accountNumber, new Account(current.accountNumber(), current.accountType(),
                    balance, current.status()));
            return 1;
        }
    }

    private static Account account(String type, String balance, String status) {
        return new Account(ACCOUNT, type, new BigDecimal(balance), status);
    }

    private static DebitAccountRequest request(String type, String amount) {
        return new DebitAccountRequest(ACCOUNT, type, new BigDecimal(amount));
    }

    private static DebitAccountResponse run(FakeAccounts accounts, DebitAccountRequest request) {
        return new DebitAccountService(accounts).execute(request);
    }

    // ---------------------------------------------------------------- RULE-001

    @Test
    void rule_001_account_not_found() {
        FakeAccounts accounts = new FakeAccounts();
        DebitAccountRequest request = new DebitAccountRequest(9999999999L, "AHO", new BigDecimal("100.00"));

        DebitAccountResponse response = run(accounts, request);

        assertThat(response.responseCode()).isEqualTo("30");
        assertThat(accounts.reads).containsExactly(9999999999L);
        assertThat(accounts.updates).isEmpty();
    }

    @Test
    void rule_001_account_not_found_even_with_zero_amount() {
        FakeAccounts accounts = new FakeAccounts();

        DebitAccountResponse response = run(accounts, request("AHO", "0.00"));

        assertThat(response.responseCode()).isEqualTo("30");
        assertThat(accounts.updates).isEmpty();
    }

    @Test
    void rule_001_other_account_exists_but_requested_one_does_not() {
        FakeAccounts accounts = new FakeAccounts().with(
                new Account(1111111111L, "AHO", new BigDecimal("500.00"), ACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "10.00"));

        assertThat(response.responseCode()).isEqualTo("30");
        assertThat(accounts.updates).isEmpty();
        assertThat(accounts.store.get(1111111111L).balance()).isEqualByComparingTo("500.00");
    }

    // ---------------------------------------------------------------- RULE-002

    @Test
    void rule_002_type_mismatch() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "500.00", ACTIVE));

        DebitAccountResponse response = run(accounts, request("COR", "50.00"));

        assertThat(response.responseCode()).isEqualTo("40");
        assertThat(accounts.updates).isEmpty();
        assertThat(accounts.store.get(ACCOUNT).balance()).isEqualByComparingTo("500.00");
    }

    @Test
    void rule_002_type_comparison_is_case_sensitive() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "500.00", ACTIVE));

        DebitAccountResponse response = run(accounts, request("aho", "50.00"));

        assertThat(response.responseCode()).isEqualTo("40");
        assertThat(accounts.updates).isEmpty();
    }

    @Test
    void rule_002_type_mismatch_takes_precedence_over_inactive_account() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "500.00", INACTIVE));

        DebitAccountResponse response = run(accounts, request("COR", "50.00"));

        assertThat(response.responseCode()).isEqualTo("40");
        assertThat(accounts.updates).isEmpty();
    }

