        DebitAccountResponse response = run(accounts, request("COR", "50.00"));

        assertThat(response.responseCode()).isEqualTo("40");
        assertThat(accounts.updates).isEmpty();
    }

    // ---------------------------------------------------------------- RULE-003

    @Test
    void rule_003_inactive_account() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "500.00", INACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "50.00"));

        assertThat(response.responseCode()).isEqualTo("10");
        assertThat(accounts.updates).isEmpty();
        assertThat(accounts.store.get(ACCOUNT).balance()).isEqualByComparingTo("500.00");
    }

    @Test
    void rule_003_inactive_takes_precedence_over_insufficient_funds() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "10.00", INACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "50.00"));

        assertThat(response.responseCode()).isEqualTo("10");
        assertThat(accounts.updates).isEmpty();
    }

    @Test
    void rule_003_inactive_account_with_zero_amount_is_still_rejected() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "500.00", INACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "0.00"));

        assertThat(response.responseCode()).isEqualTo("10");
        assertThat(accounts.updates).isEmpty();
    }

    // ---------------------------------------------------------------- RULE-004

    @Test
    void rule_004_insufficient_balance_by_one_cent() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "100.00", ACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "100.01"));

        assertThat(response.responseCode()).isEqualTo("20");
        assertThat(accounts.updates).isEmpty();
        assertThat(accounts.store.get(ACCOUNT).balance()).isEqualByComparingTo("100.00");
    }

    @Test
    void rule_004_balance_equal_to_amount_is_allowed() {
