        DebitAccountResponse response = run(accounts, request("AHO", "100.00"));

        assertThat(response.responseCode()).isEqualTo("00");
        assertThat(response.balance()).isEqualByComparingTo("0.00");
        assertThat(accounts.updates).hasSize(1);
        assertThat(accounts.store.get(ACCOUNT).balance()).isEqualByComparingTo("0.00");
    }

    @Test
    void rule_004_balance_one_cent_above_amount_is_allowed() {
        FakeAccounts accounts = new FakeAccounts().with(account("AHO", "100.00", ACTIVE));

        DebitAccountResponse response = run(accounts, request("AHO", "99.99"));

        assertThat(response.responseCode()).isEqualTo("00");
        assertThat(response.balance()).isEqualByComparingTo("0.01");
    }

